import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"Attack Testing & Detection Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/performance/attack-testing.md","filePath":"openshield-xdp/performance/attack-testing.md","lastUpdated":1785481554000}'),r={name:"openshield-xdp/performance/attack-testing.md"};function d(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="attack-testing-detection-analysis" tabindex="-1">Attack Testing &amp; Detection Analysis <a class="header-anchor" href="#attack-testing-detection-analysis" aria-label="Permalink to &quot;Attack Testing &amp; Detection Analysis&quot;">​</a></h1><p>This page documents the results of live attack testing against OpenShield-XDP, the bugs that testing uncovered, and how the dynamic-detection configuration values change firewall behavior in practice. Use it to tune <code>dynamic:</code> thresholds for your own traffic profile.</p><h2 id="test-methodology-and-its-pitfalls" tabindex="-1">Test Methodology (and Its Pitfalls) <a class="header-anchor" href="#test-methodology-and-its-pitfalls" aria-label="Permalink to &quot;Test Methodology (and Its Pitfalls)&quot;">​</a></h2><p>Live DDoS simulation against your own server is harder than it looks. Three traps we hit — you will hit them too:</p><h3 id="_1-docker-bridge-traffic-never-reaches-xdp" tabindex="-1">1. Docker/bridge traffic never reaches XDP <a class="header-anchor" href="#_1-docker-bridge-traffic-never-reaches-xdp" aria-label="Permalink to &quot;1. Docker/bridge traffic never reaches XDP&quot;">​</a></h3><p>Packets sent from a local Docker container to the host&#39;s <strong>own public IP</strong> are delivered locally through the Docker bridge (<code>pterodactyl0</code>, <code>docker0</code>, ...). The kernel sees the destination is local and hands the packet to the local stack — it <strong>never ingresses the physical interface</strong>, so an XDP program attached to <code>eth0</code>/<code>enp3s0</code> cannot see it, let alone count or drop it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>container → veth → pterodactyl0 → (local delivery) → host stack</span></span>
<span class="line"><span>                                  ✗ enp3s0 XDP sees nothing</span></span></code></pre></div><p>This is expected XDP behavior (XDP hooks are per-interface, at driver ingress), not a firewall bug. Consequence: <strong>container-based attack tests against your own IP are invalid</strong> — you are testing nothing. The same applies to any locally-routed traffic.</p><h3 id="_2-spoofed-source-floods-are-filtered-by-the-sender-s-provider" tabindex="-1">2. Spoofed-source floods are filtered by the <em>sender&#39;s</em> provider <a class="header-anchor" href="#_2-spoofed-source-floods-are-filtered-by-the-sender-s-provider" aria-label="Permalink to &quot;2. Spoofed-source floods are filtered by the *sender&#39;s* provider&quot;">​</a></h3><p><code>hping3 --rand-source</code> from an external VPS produces packets with spoofed sources. Most hosting providers apply egress anti-spoofing (uRPF/ACL), so those packets are dropped before they leave the sender&#39;s network. Your firewall logs show nothing and it looks like &quot;detection is broken&quot; — the traffic simply never arrived.</p><h3 id="_3-vps-to-vps-traffic-may-be-blocked-entirely" tabindex="-1">3. VPS-to-VPS traffic may be blocked entirely <a class="header-anchor" href="#_3-vps-to-vps-traffic-may-be-blocked-entirely" aria-label="Permalink to &quot;3. VPS-to-VPS traffic may be blocked entirely&quot;">​</a></h3><p>Some provider pairs block or heavily filter inter-network traffic (ICMP, UDP, or whole prefixes). Verify plain TCP connectivity between attacker and target <strong>before</strong> drawing conclusions from a missing flood.</p><h3 id="what-actually-works" tabindex="-1">What actually works <a class="header-anchor" href="#what-actually-works" aria-label="Permalink to &quot;What actually works&quot;">​</a></h3><ul><li>A real external host on a normal residential/cloud connection sending <strong>uns spoofed</strong> floods (<code>hping3 -i u100..u500</code>), with the attacker&#39;s IP whitelisted so management access survives the test.</li><li>Watching <code>total_*_packets</code> counters in <code>global_stats_map</code> (or the telemetry socket) to confirm arrival — &quot;packets sent&quot; on the attacker proves nothing.</li></ul><h2 id="bugs-found-by-testing" tabindex="-1">Bugs Found by Testing <a class="header-anchor" href="#bugs-found-by-testing" aria-label="Permalink to &quot;Bugs Found by Testing&quot;">​</a></h2><p>All of these were found by the test campaign and are fixed in the current build.</p><h3 id="f1-—-attack-state-never-cleared-under-attack-for-3-hours" tabindex="-1">F1 — Attack state never cleared (&quot;under attack&quot; for 3+ hours) <a class="header-anchor" href="#f1-—-attack-state-never-cleared-under-attack-for-3-hours" aria-label="Permalink to &quot;F1 — Attack state never cleared (&quot;under attack&quot; for 3+ hours)&quot;">​</a></h3><p><strong>Symptom:</strong> TUI/status showed <code>UNDER ATTACK</code> for hours after traffic returned to normal; Discord &quot;attack ended&quot; webhooks never fired.</p><p><strong>Root cause:</strong> attack recovery required traffic to fall below <code>baseline_pps × spike_recovery_factor</code> (≈ 96 pps on the test server) for <code>spike_recovery_time</code> (60) consecutive seconds. On any server with real background traffic (game servers, panels, API chatter), noise alone exceeds <code>baseline × 1.5</code> regularly, so the recovery counter kept resetting. Attacks only ended via the 300 s absolute timeout, then instantly re-triggered on the next noise burst — a permanent attack state.</p><p><strong>Fix:</strong> recovery is now <strong>spike-relative</strong>: the attack ends when traffic stays below <code>spike_threshold × spike_recovery_factor</code> for <code>spike_recovery_time</code> seconds. The factor must be <code>&lt; 1.0</code> (default <code>0.7</code>) so the recovery band sits below the trigger band. Mitigation (bans, rate limits) is independent of the attack state, so ending the state promptly never weakens protection. New defaults: <code>spike_recovery_factor: 0.7</code>, <code>spike_recovery_time: 10</code>.</p><h3 id="f2-—-end-→-re-detect-loop" tabindex="-1">F2 — End → re-detect loop <a class="header-anchor" href="#f2-—-end-→-re-detect-loop" aria-label="Permalink to &quot;F2 — End → re-detect loop&quot;">​</a></h3><p><strong>Symptom:</strong> after an attack ended (timeout or recovery), the next small burst immediately opened a new attack, so tracker records accumulated multi-hour durations.</p><p><strong>Fix:</strong> 10-second post-attack cooldown — re-triggering within 10 s of an attack end requires a clearly renewed spike (≥ 2× threshold), not hover traffic.</p><h3 id="f3-—-udp-icmp-floods-mis-classified-as-tcp-flood" tabindex="-1">F3 — UDP/ICMP floods mis-classified as TCP_FLOOD <a class="header-anchor" href="#f3-—-udp-icmp-floods-mis-classified-as-tcp-flood" aria-label="Permalink to &quot;F3 — UDP/ICMP floods mis-classified as TCP_FLOOD&quot;">​</a></h3><p><strong>Root cause:</strong> <code>classifyType</code> computed per-protocol deviation from baseline as <code>current / baseline</code>. When the baseline had <strong>zero</strong> of a protocol (a server that never sees UDP/ICMP), deviation stayed 0 and the UDP/ICMP branch silently failed, falling through to the generic TCP/MIXED fallback.</p><p><strong>Fix:</strong> a protocol that is absent from the baseline but present at ≥ 100 pps now counts as effectively infinite deviation, so UDP floods classify as <code>UDP_FLOOD</code>, ICMP floods as <code>ICMP_FLOOD</code> even on servers with zero baseline for that protocol.</p><h3 id="f4-—-one-shot-classification-at-trigger-time" tabindex="-1">F4 — One-shot classification at trigger time <a class="header-anchor" href="#f4-—-one-shot-classification-at-trigger-time" aria-label="Permalink to &quot;F4 — One-shot classification at trigger time&quot;">​</a></h3><p><strong>Root cause:</strong> the attack type was computed once, at trigger time — often mid-ramp when protocol shares are not yet representative.</p><p><strong>Fix:</strong> the classifier re-classifies every 5 seconds during an attack. A type switch requires the same new type 3 consecutive times <strong>and</strong> ≥ 60 s since the last accepted switch (anti-flap). Re-classifications propagate to the tracker, the forensics report, and Discord alerts.</p><h3 id="f5-—-syn-ack-floods-invisible-to-the-classifier" tabindex="-1">F5 — SYN-ACK floods invisible to the classifier <a class="header-anchor" href="#f5-—-syn-ack-floods-invisible-to-the-classifier" aria-label="Permalink to &quot;F5 — SYN-ACK floods invisible to the classifier&quot;">​</a></h3><p><strong>Fix:</strong> added a global <code>total_synack_packets</code> counter to the BPF stats struct; the collector now computes real <code>synack_pps</code>. SYN-ACK reflector floods are now distinguishable from pure SYN floods.</p><h3 id="f6-—-systemd-service-could-not-restart-after-unload-reboot" tabindex="-1">F6 — systemd service could not restart after unload/reboot <a class="header-anchor" href="#f6-—-systemd-service-could-not-restart-after-unload-reboot" aria-label="Permalink to &quot;F6 — systemd service could not restart after unload/reboot&quot;">​</a></h3><p><strong>Symptom:</strong> <code>systemctl start openshield-loader</code> failed with <code>Failed to set up mount namespacing: /sys/fs/bpf/openshield: No such file or directory</code> after <code>openshield unload</code> or a reboot.</p><p><strong>Root cause:</strong> <code>ReadWritePaths=/sys/fs/bpf/openshield /var/run/openshield ...</code> fails the whole mount namespace when a listed path is missing — and BPF pins are removed on unload, <code>/run</code> is tmpfs after reboot.</p><p><strong>Fix:</strong> the unit now uses <code>RuntimeDirectory</code>/<code>StateDirectory</code>/<code>LogsDirectory</code> (auto-created by systemd), <code>ExecStartPre=mkdir -p /sys/fs/bpf/openshield</code>, and <code>ReadWritePaths=/sys/fs/bpf</code>. <code>ProtectKernelTunables</code> had to be dropped — it remounts <code>/sys</code> read-only inside the namespace, breaking both the mkdir and map pinning.</p><h3 id="f7-—-one-stalled-tui-client-could-freeze-telemetry-for-everyone" tabindex="-1">F7 — One stalled TUI client could freeze telemetry for everyone <a class="header-anchor" href="#f7-—-one-stalled-tui-client-could-freeze-telemetry-for-everyone" aria-label="Permalink to &quot;F7 — One stalled TUI client could freeze telemetry for everyone&quot;">​</a></h3><p><strong>Symptom:</strong> a TUI tab stuck on <code>Connected to loader — waiting for telemetry...</code> while another tab worked fine.</p><p><strong>Root cause:</strong> <code>Broadcast</code> wrote snapshots to every subscribed client <strong>synchronously while holding the server mutex</strong>, with a 5 s write deadline per client. One suspended or slow client (Ctrl-Z, laggy SSH session) stalled the whole fan-out for seconds per interval; it could also delay <code>Stop()</code>. There was also a latent data race: request responses were written from the handler goroutine while <code>Broadcast</code> wrote to the same <code>bufio.Writer</code>.</p><p><strong>Fix:</strong> each client now has its own buffered outbound queue (depth 16) drained by a dedicated writer goroutine. <code>Broadcast</code> does a non-blocking send per client — a client that falls behind simply misses intermediate snapshots and can never stall others. All writes are serialized through a per-client mutex, eliminating the race.</p><h2 id="configuration-parameter-impact-analysis" tabindex="-1">Configuration Parameter Impact Analysis <a class="header-anchor" href="#configuration-parameter-impact-analysis" aria-label="Permalink to &quot;Configuration Parameter Impact Analysis&quot;">​</a></h2><p>What we observed changing each value on a live server (baseline ≈ 60 pps, noisy game-server background):</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Observed effect</th></tr></thead><tbody><tr><td><code>attack_pps_threshold</code></td><td><code>0</code> (auto)</td><td><code>0</code> = use the learned spike threshold (≈ 4× baseline, floored by <code>attack_min_pps</code>). Set explicitly (e.g. <code>2000</code>) on busy servers to stop legit burst false-positives.</td></tr><tr><td><code>attack_min_pps</code></td><td><code>1000</code></td><td>Absolute floor for the trigger threshold. Prevents a freshly-seeded low baseline from making the threshold tiny. Real bursts (package downloads at 5–8k pps) still exceed it — see note below.</td></tr><tr><td><code>attack_trigger_time</code></td><td><code>3</code> (s)</td><td>Consecutive seconds above threshold before attack state. <code>3</code> catches floods fast but also 3-second legit spikes; <code>5–8</code> absorbs short download bursts at the cost of slower detection.</td></tr><tr><td><code>spike_recovery_factor</code></td><td><code>0.7</code></td><td>Fraction of the spike threshold below which the attack ends. <strong>Must be &lt; 1.0.</strong> <code>0.5</code> = ends sooner (flappier), <code>0.9</code> = ends later (smoother). Values ≥ 1.0 are clamped to <code>0.7</code>.</td></tr><tr><td><code>spike_recovery_time</code></td><td><code>10</code> (s)</td><td>Consecutive seconds in the recovery band before the attack ends. <code>60</code> (old default) left the firewall reporting &quot;under attack&quot; a full minute after the flood stopped; <code>10–15</code> tracks reality.</td></tr><tr><td><code>attack_max_duration</code></td><td><code>300</code> (s)</td><td>Hard cap on attack state. After it fires, the cooldown (10 s) prevents instant re-trigger loops.</td></tr><tr><td><code>new_src_pps</code> / suspicion engine</td><td>profile</td><td>Drives per-source scoring and bans; unaffected by the attack-state fixes — bans keep dropping traffic regardless of the global state.</td></tr></tbody></table><h3 id="false-positives-you-should-expect" tabindex="-1">False positives you should expect <a class="header-anchor" href="#false-positives-you-should-expect" aria-label="Permalink to &quot;False positives you should expect&quot;">​</a></h3><p><strong>High-speed downloads look like floods.</strong> A <code>apt</code>/<code>wget</code> at 5–8k pps from 2–3 mirror IPs trips the spike detector (<code>TCP_FLOOD</code>) on a server whose baseline is ~60 pps. This is inherent to any spike detector on a quiet server. Mitigations:</p><ul><li>Raise <code>attack_pps_threshold</code> to a value above your normal burst level (e.g. <code>2000</code>–<code>5000</code>).</li><li>Raise <code>attack_trigger_time</code> to <code>5</code>–<code>8</code> so short downloads never trip it.</li><li>Whitelist your package mirrors/CDN ranges.</li><li>Note that detection does not equal impact: state changes and alerts fire, but legit flows only get dropped if they also trip the per-source suspicion engine.</li></ul><h2 id="recommended-profiles" tabindex="-1">Recommended Profiles <a class="header-anchor" href="#recommended-profiles" aria-label="Permalink to &quot;Recommended Profiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Server type</th><th><code>attack_pps_threshold</code></th><th><code>attack_trigger_time</code></th><th><code>spike_recovery_factor</code></th><th><code>spike_recovery_time</code></th></tr></thead><tbody><tr><td>Quiet (APIs, small sites)</td><td><code>0</code> (auto)</td><td><code>3</code></td><td><code>0.7</code></td><td><code>10</code></td></tr><tr><td>Game server (noisy baseline)</td><td><code>2000</code>–<code>3000</code></td><td><code>4</code></td><td><code>0.7</code></td><td><code>10</code></td></tr><tr><td>Heavy download/CDN origin</td><td><code>5000</code>+</td><td><code>6</code></td><td><code>0.6</code></td><td><code>15</code></td></tr></tbody></table>`,47)])])}const u=t(r,[["render",d]]);export{f as __pageData,u as default};
